import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    t = data[0]
    idx = 1
    out = []

    for _ in range(t):
        n = data[idx]
        idx += 1
        a = data[idx:idx + 2 * n]
        idx += 2 * n

        adjacent_same = [False] * (n + 1)
        first_edge = {}
        candidate = set()

        for i in range(2 * n - 1):
            x, y = a[i], a[i + 1]

            if x == y:
                adjacent_same[x] = True
                continue

            if x > y:
                x, y = y, x
            key = (x, y)

            if key in first_edge:
                if i - first_edge[key] > 1:
                    candidate.add(key)
            else:
                first_edge[key] = i

        ans = 0
        for x, y in candidate:
            if not adjacent_same[x] and not adjacent_same[y]:
                ans += 1

        out.append(str(ans))

    print("\n".join(out))

if __name__ == "__main__":
    solve()

